fn min_by_key<K, F>(self, f: F) -> Option<Self::Item>
where
    K: Ord + Send,
    F: Sync + Send + Fn(&Self::Item) -> K,
{
    fn key<T, K>(f: impl Fn(&T) -> K) -> impl Fn(T) -> (K, T) {
        move |x| (f(&x), x)
    }

    fn min_key<T, K: Ord>(a: (K, T), b: (K, T)) -> (K, T) {
        match (a.0).cmp(&b.0) {
            Ordering::Greater => b,
            _ => a,
        }
    }

    let (_, x) = self.map(key(f)).reduce_with(min_key)?;
    Some(x)
}

